import re

OPEN_DICT = re.compile(r"^(?P<indent>\s*)(?P<key>\S(?:.*?\S)?) \{\s*$")
OPEN_LIST = re.compile(r"^(?P<indent>\s*)(?P<key>\S(?:.*?\S)?) \[(?: \((?P<value>[^)]*)\))?\s*$")
CLOSE = re.compile(r"^\s*[\]}]\s*$")
KV = re.compile(r"^\s*(?P<key>[^:]+?):\s*(?P<value>.*?)\s*$")
ITEM = re.compile(r"^\s*(?P<name>\S+)(?: \((?P<value>[^)]*)\))?\s*$")


def read(lines, i, n):
    """Parse lines[i:] up to the closing bracket of this level; -> (entries, next i).
    An entry is (key, value, first line, last line); value is a str,
    ("dict", entries) or ("list", value, entries)."""
    out = []
    while i < n:
        ln = lines[i]
        if not ln.strip():
            i += 1; continue
        if CLOSE.match(ln):
            return out, i + 1
        m = OPEN_DICT.match(ln)
        if m:
            kids, j = read(lines, i + 1, n)
            out.append((m.group("key"), ("dict", kids), i, j - 1)); i = j; continue
        m = OPEN_LIST.match(ln)
        if m:
            kids, j = read(lines, i + 1, n)
            out.append((m.group("key"), ("list", m.group("value") or "", kids), i, j - 1)); i = j; continue
        m = KV.match(ln)
        if m:
            out.append((m.group("key"), m.group("value"), i, i)); i += 1; continue
        m = ITEM.match(ln)
        if m:
            out.append(("", m.group("name"), i, i)); i += 1; continue
        out.append(("?", ln.strip(), i, i)); i += 1
    return out, i


def flatten(entries, prefix, rec, subs):
    """Leaves into REC with dotted keys; a bit-set list into KEY + KEY.set;
    repeated records (a list of {}, or a key repeated as {}) into SUBS."""
    counts = {}
    for key, val, s, e in entries:
        if not isinstance(val, str) and val[0] == "dict":
            counts[key] = counts.get(key, 0) + 1
    for key, val, s, e in entries:
        name = prefix + key
        if isinstance(val, str):
            rec[name] = val
        elif val[0] == "dict":
            if counts[key] > 1:
                subs.setdefault(name, []).append((key, val, s, e))
            else:
                flatten(val[1], name + ".", rec, subs)
        else:
            items = [k for k in val[2] if isinstance(k[1], str)]
            dicts = [k for k in val[2] if not isinstance(k[1], str)]
            if val[1]:
                rec[name] = val[1]
                rec[name + ".set"] = ",".join(k[1] for k in items)
            elif not dicts:
                rec[name] = ",".join(k[1] for k in items)
            if dicts:
                subs.setdefault(name, []).extend(dicts)


def table(name, dicts, parent_col, parent_val, blocks):
    """One table block from a list of ("dict"|"list") entries."""
    recs, rec_lines, pending = [], [], []
    varied = len({k for k, v, s, e in dicts}) > 1
    for k, v, s, e in dicts:
        rec, subs = {}, {}
        if parent_col:
            rec[parent_col] = parent_val
        if varied:
            rec["entry"] = k
        flatten(v[1] if v[0] == "dict" else v[2], "", rec, subs)
        recs.append(rec); rec_lines += list(range(s, e + 1))
        for sname, kids in subs.items():
            pending.append((name + "." + sname, kids, next(iter(rec.values()), k)))
    keys = []
    for r in recs:
        for k in r:
            if k not in keys:
                keys.append(k)
    recs = [{k: r.get(k, "") for k in keys} for r in recs]
    blocks.append({"name": name, "kind": "table", "lines": rec_lines, "records": recs})
    for sname, kids, pval in pending:
        table(sname, kids, "parent", pval, blocks)


def parse(lines):
    entries, _ = read(lines, 0, len(lines))
    skip, blocks, top, top_lines = [], [], {}, []
    for key, val, s, e in entries:
        if isinstance(val, str):
            top[key] = val; top_lines.append(s)
        elif val[0] == "dict":
            rec, subs = {}, {}
            flatten(val[1], "", rec, subs)
            blocks.append({"name": key, "kind": "kv", "lines": list(range(s, e + 1)), "records": [rec]})
            for sname, kids in subs.items():
                table(key + "." + sname, kids, "", "", blocks)
        else:
            skip += [s, e]
            items = [k for k in val[2] if isinstance(k[1], str)]
            dicts = [k for k in val[2] if not isinstance(k[1], str)]
            if items or not dicts:
                top[key] = ",".join(k[1] for k in items); top_lines += [k[2] for k in items]
            if dicts:
                table(key, dicts, "", "", blocks)
    if top:
        blocks.insert(0, {"name": "file", "kind": "kv", "lines": top_lines, "records": [top]})
    return {"blocks": blocks, "skip": skip}
